        if lease is None or lease <= 0:
            return ("invalid",)
    return (
        "ok",
        {
            "to_server": to_server,
            "msg": msg_type,
            "xid": xid,
            "chaddr": _format_mac(client_mac),
            "ciaddr": _ipv4_dotted(ciaddr),
            "yiaddr": _ipv4_dotted(yiaddr),
            "lease": lease,
        },
